    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t2 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t3 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1)
);

CREATE TABLE t4 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 SMALLINT NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t1(c1)
);

CREATE TABLE t5 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    c3 DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t1(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

CREATE TABLE t6 (
    c1 VARCHAR NOT NULL,
    c2 VARCHAR NOT NULL,
    PRIMARY KEY (c1, c2),
    FOREIGN KEY (c1) REFERENCES t3(c1),
    FOREIGN KEY (c2) REFERENCES t2(c1)
);

counterexample:
INSERT INTO t1 (c1, c2) VALUES ('x1', 'dummy');
INSERT INTO t1 (c1, c2) VALUES ('x2', 'dummy');
INSERT INTO t1 (c1, c2) VALUES ('y1', 'dummy');
INSERT INTO t1 (c1, c2) VALUES ('y2', 'dummy');
INSERT INTO t3 (c1, c2) VALUES ('a', 'dummy');
INSERT INTO t3 (c1, c2) VALUES ('b', 'dummy');
INSERT INTO t4 (c1, c2, c3) VALUES ('a', 'x1', 2);
INSERT INTO t4 (c1, c2, c3) VALUES ('a', 'x2', 3);
INSERT INTO t4 (c1, c2, c3) VALUES ('b', 'y1', 1);
INSERT INTO t4 (c1, c2, c3) VALUES ('b', 'y2', 4);

